        /** Audio extensions. */
        Audio: Object.freeze({ mp3: 1, wav: 1, aac: 1, flac: 1, m4a: 1, m4b: 1, opus: 1, oga: 1, weba: 1 }),
        /** Source code / markup extensions. */
        Programming: Object.freeze({ js: 1, json: 1, css: 1, html: 1, xml: 1, cs: 1, cpp: 1, c: 1, h: 1, vbs: 1, bat: 1, vb: 1 }),
