        Sw.DevOptions.Register("Sw.Page.Loading", { Element: "element", Target: "element", Text: "string", Opaque: "boolean", Icon: "string", Delay: { Type: "number", Min: 0 } });
        Sw.DevOptions.Register("Sw.Page.Announce", { Assertive: "boolean" });
