        const down = ev => {
            if (ev.target !== e || !IsPureEvent(ev))
                return;
            if (ev.key === "Enter") {
                ev.preventDefault();
                e.click();
            }
            else if (ev.key === " ")
                ev.preventDefault();
        };
        /** Space (key up) clicks the element. */
        const up = ev => {
            if (ev.target !== e || !IsPureEvent(ev) || ev.key !== " ")
                return;
            ev.preventDefault();
            e.click();
        };
        e.addEventListener("keydown", down);
        e.addEventListener("keyup", up);
