    // ------------------------------------------------------------------ common methods

    /** The elements that can take the focus inside a component. */
    const FocusSel = "input:not([disabled]), textarea:not([disabled]), select:not([disabled]), button:not([disabled]), [tabindex]:not([tabindex='-1'])";

