            const anchorE = anchor && anchor.nodeType === 1 ? anchor : null;
            if (anchorE && anchorE.SwMenu && !anchorE.SwMenu.Closed) {
                const open = anchorE.SwMenu;
                open.Close();
                return open;
            }
