        e.removeAttribute("title");
        const c = Classes;
        e.classList.remove(c.Right, c.Left, c.Center, c.Null, c.False, c.Mono, c.Text, c.Actions, c.Capped, c.Link, "sw-cell-dt", "sw-cell-dt-utc", "sw-cell-dt-local");
        setClick(e, null);
        removeCopy(e);
        return true;
